#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <string_view>

enum class Level { debug, info, warning, error };

std::string_view levelName(Level level)
{
    switch (level)
    {
    case Level::debug: return "DEBUG";
    case Level::info: return "INFO";
    case Level::warning: return "WARN";
    default: return "ERROR";
    }
}

template <typename... Args>
void log(Level level, const Args&... args)
{
    std::ostringstream line{};          // like std::cout, but collects the text in a string (lesson 10.05)
    (line << ... << args);              // a fold expression: line << a1 << a2 << ...
    std::cout << '[' << levelName(level) << "] " << line.str() << '\n';
}

